/** KRISHNA TOOLS — Privacy Policy. Describes what the site really stores (see api/upload.php, includes/analytics.php, cron cleanup). */
require_once __DIR__ . '/includes/legal.php';
$s = kt_shop();
kt_legal_page('Privacy Policy', 'How Krishna Tools handles your files and data: most tools run in your browser, uploads are deleted within 2 hours, and we never sell your data.', '2026-11-28', [
    ['Who we are', '<p>Krishna Tools (tools.akdwk.in) is run by ' . e($s['name']) . ', a computer and CCTV shop in ' . e($s['city']) . '. This policy explains what information the website collects, why, and what control you have. If you have a question about it, contact us using the details at the end of this page.</p>'],
    ['Your files stay on your device for most tools', '<p>Most of our tools — image converters and resizers, most PDF tools, calculators, text tools, QR and card makers — work entirely inside your web browser. The file or text you use is processed on your own phone or computer and is <b>not uploaded</b> to our server.</p><p>A few tools need our server (for example some PDF compression or document conversions). For those, your file is uploaded over an encrypted HTTPS connection to a temporary folder, processed, and <b>deleted automatically within 2 hours</b>. Shared download links you create yourself expire on the date shown, and files saved in a paid account are deleted when they expire. We do not look at, copy or reuse the content of your files.</p>'],
    ['Information we collect', '<ul class="list-disc ml-6 space-y-1"><li><b>Usage statistics.</b> When you open a page we record the page address, the referring site, the time, your approximate city (from your IP address) and a random visitor ID stored in your browser. This tells us which tools are useful. It is not used to identify you personally.</li><li><b>Tool usage counts.</b> When you use a tool we count it, so we can see which tools to improve and, for free accounts, apply the daily limit.</li><li><b>Account details</b> (only if you register): name, email, mobile number and a securely hashed password. Your mobile number is used for login OTPs and account messages on WhatsApp.</li><li><b>Contact form messages:</b> the name, email or phone and message you send us.</li><li><b>Payments</b> (only for paid plans): handled by Razorpay. We receive the payment ID, amount and status — never your card, UPI PIN or bank details.</li></ul>'],
    ['Cookies and browser storage', '<p>We use a session cookie to keep you logged in and to protect forms against misuse. Your browser\'s local storage keeps your preferences — dark mode, favourite and recently used tools, and details you choose to save in a tool (such as your shop name on a quotation). This stays on your device and you can clear it at any time from your browser settings.</p><p>If Google Analytics is enabled, Google sets its own cookies to measure visits and tool events; see Google\'s privacy policy for details. If you allow push notifications, your browser registers with our notification service (notification.akdwk.in) so we can send occasional updates; you can turn this off in your browser settings.</p>'],
    ['Partner and referral links', '<p>Some visitors arrive through partner links (for example a link with <code>?ref=</code>). We record which partner referred a sign-up or a paid plan so that the partner programme (earn.akdwk.in) can credit them. Only the referral code and the event (such as sign-up or payment) are shared — not the content of anything you do with the tools.</p>'],
    ['How we use information', '<ul class="list-disc ml-6 space-y-1"><li>to run the tools and your account;</li><li>to answer your messages and support requests;</li><li>to understand which tools are used, fix problems and improve the site;</li><li>to prevent abuse, such as automated attacks or excessive use.</li></ul><p class="mt-2">We do not sell or rent your personal information, and we do not use the content of your files for advertising or for training anything.</p>'],
    ['Who we share it with', '<p>Only with the services needed to run the site: our web hosting provider, Razorpay for payments, the WhatsApp messaging gateway for OTPs and messages, Google Analytics (if enabled), an IP-to-city lookup service for statistics, and the partner programme for referral credit. We may also disclose information if required by Indian law or a valid order of a court or authority.</p>'],
    ['How long we keep it', '<p>Temporary uploads: up to 2 hours. Usage statistics: kept in summary form for reporting. Account information: for as long as your account is active; ask us to delete it and we will remove your account and personal details, except records we must keep by law (such as payment invoices).</p>'],
    ['Your choices and rights', '<p>You can use almost every tool without an account. You may ask us to show, correct or delete the personal information we hold about you, or to stop sending you WhatsApp messages, by contacting us. You can clear cookies and local storage in your browser at any time. These rights are in line with India\'s Digital Personal Data Protection Act, 2023.</p>'],
    ['Children', '<p>The site is meant for general audiences. Accounts are intended for people aged 18 or older, or used with a parent\'s or guardian\'s permission.</p>'],
    ['Changes to this policy', '<p>If we change how we handle information, we will update this page and the "last updated" date above.</p>'],
    ['Contact', '<p>For any privacy question or request, write to us through the <a class="underline" href="' . SITE_URL . '/contact.php">contact page</a> or WhatsApp ' . e($s['phone']) . '.</p>'],
]);
